var t=`1105-ohn-no-khao-swe`;var n=`world-1105`;var s=`MM`;var a=`southeast-asia`;var o=4;var r=54;var l={en:`Ohn No Khao Swè`,ua:`Он но кхао све`};var h={en:`Ohn No Khao Swè is a dish from Myanmar prepared with shallot, garlic, chicken thigh, coconut milk. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Он но кхао све, страва кухні країни М'янма, яку готують із таких продуктів: цибуля шалот, часник, куряче стегно, кокосове молоко. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var g=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 7 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 7 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:7,i:[[`shallot`,160,`g`],[`garlic`,4,`clove`],[`ground-turmeric`,6,`g`],[`canola-oil`,35,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 27 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 27 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:27,i:[[`chicken-thigh`,700,`g`],[`coconut-milk`,750,`ml`],[`chicken-stock`,550,`ml`],[`fish-sauce`,30,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 7 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 7 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:7,i:[[`egg-noodles`,450,`g`],[`water`,1e3,`ml`]]},{en:`Boil the eggs for about 9 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 9 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:9,i:[[`chicken-egg`,4,`pcs`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:4,i:[[`cilantro`,25,`g`],[`lime`,2,`pcs`]]}];var d={slug:t,id:n,country:`MM`,region:a,servings:4,minutes:54,title:l,text:h,steps:g};export{s as country,d as default,n as id,r as minutes,a as region,o as servings,t as slug,g as steps,h as text,l as title};